window.__CAT__=window.__CAT__||[];window.__CAT__.push([{"no": 28, "id": "SIe7aphoA1Q", "title": "Spend a long years with you - Chapter 01（serial）", "title_zh": "与你共度漫长岁月 - 第一章（连载） (Spend a long years with you - Chapter 01（serial）)", "duration": "00:09:05", "link": "https://www.youtube.com/watch?v=SIe7aphoA1Q", "enriched": true, "lines": [{"ts": "00:00:00", "text": "字同。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:05", "text": "怎能孤来了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:08", "text": "也不到门口迎接。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "孤刚为你摘了柿子。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "你且瞧瞧。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:19", "text": "高。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:20-00:00:33", "text": "那算什么高（重复8次，已合并）。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:35", "text": "比识于二弟四哥一同习武时。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "爬得比那高。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "摔不着。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:40", "text": "前两日你总惦记着。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "大哥府中那个柿子树。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "今日收了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:46", "text": "自然先给你尝尝。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:48", "text": "原来子同记挂得。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "竟是孤偷买了大哥的柿子。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:53", "text": "他会不会生气。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:56", "text": "莫说是大哥府中的柿子。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:59", "text": "并是天下的柿子收了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "你想吃。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "孤便摘于你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "谁敢说个不字？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "翻墙头算的什么？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "真的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "不记得孤还是太子的时候。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "翻你的墙头了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "爸爸。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "脸红了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:30", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:01:33", "text": "你这个娇羞的模样了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "真让孤喜欢得几。", "speaker": "爸爸", "tone": "宠溺", "sound": []}, {"ts": "00:01:39", "text": "你这柿子甜不甜。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "好吃的话。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "明日再给你送些。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "慢些吃。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:52", "text": "小时候一样。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:55", "text": "这没人予你尝。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:58", "text": "别太贪吃话的独自。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:02", "text": "你看看。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:05", "text": "这不就开始痛了。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:09", "text": "吃东西还跟个孩子吃的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:13", "text": "就拿好吃的没得分寸。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "痛的这般厉害。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:02:22", "text": "手伸过来。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:25", "text": "过去检查一番。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:28", "text": "拿过来。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:31", "text": "不听话是想要受罚。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:34", "text": "手这般厉害。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:36", "text": "是不是又偷吃冰了？", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:02:39", "text": "老实回答。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "若是扎黄。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:44", "text": "乘法翻倍。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "已到九月天气转凉。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "便还这些余暑也入秋了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:52", "text": "还吃完贪凉。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "孤可又嘱咐过。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:02:58", "text": "吃冰不可放肆。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:03:00", "text": "既是有。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "怎还如此不听话。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:03:06-00:03:11", "text": "回答。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "孤面前眼泪不管用。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "犯了错便是要罚。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:03:22", "text": "自己说。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "多少下。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "二十。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:31", "text": "自作聪明是。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:34", "text": "想加倍了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:40", "text": "就算是。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "今日念你肚痛。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:44", "text": "便吃大柿子下。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:46", "text": "余下的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "明日不痛了再换。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:50", "text": "可听明白了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "现在请店里没有他人。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "把裙摆心看。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "好好地趴在手上。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:06", "text": "好好保守。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:12", "text": "若是错了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:18", "text": "便重来。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "知道了吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:04:30", "text": "那就开始。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "去。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:42", "text": "哎呀！", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:04:46", "text": "绑了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:50", "text": "给你揉揉，揉揉，揉揉，便不痛了。", "speaker": "爸爸", "tone": "撒娇", "sound": []}, {"ts": "00:04:55", "text": "我自然心疼，脸都花了，怎能不心疼。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:05:00", "text": "但是，有约在先，犯错，自是要惩罚的。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:05:05", "text": "惩罚是为了你听话些，常尝教训。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:05:11", "text": "怎能日日提醒你性子糊涂来。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:16", "text": "就今日，贪凉肚痛了，不难受啊！", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:05:21", "text": "若是不拦着你些，病了个怎么办。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:27", "text": "故让下人跟你熬碗姜汤水，暖暖身子。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "明日再摘几个柿子，叫人放在瓶里面冰镇着。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "凉好了，撒些白糖，再拿来给你，看好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:05:59", "text": "拿纸擦擦，拿纸擦擦。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:06", "text": "梦到什么了，需要这么开心。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:13", "text": "梦到自己是古代的皇后啊！", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "哎呦，你这梦还挺幸福的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:21", "text": "怪不得，叫你几回都不愿意醒了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:25", "text": "我想梦里的皇上。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:32", "text": "看了有些事，你还记得呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:06:39", "text": "坐着也能睡着，睡这么久腿麻了没。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:47", "text": "你还好意思提讲，坐，听一半就睡着了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:52", "text": "我们还坐前台讲时看的疫情而处。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:06:57", "text": "刚刚还过来问我，是不是讲的没意思，把你给讲困了。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:07:02", "text": "我怎么回答。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:07", "text": "我说你是考拉转世，每天的睡眠市场啊，要远超长人。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:12", "text": "小时候，我说错了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:16", "text": "上次是谁，说好一起吃饭，结果睡过头让我等了两个小时。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:25", "text": "我没当然没有这么说，逗你玩的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "我说你不太了解唐的历史，昨天补步了一下，所以睡得晚了一点。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:38", "text": "现在觉得不好意思啊！", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:41", "text": "没事。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:07:45", "text": "这个导师跟我关系还挺好的，不会真不高兴。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:49", "text": "你看我跟你圆场多好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:53", "text": "邀请你听下次讲座了，还特意叮嘱我。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:07:57", "text": "不要客气，有问题可以问他吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:08:01", "text": "你看啊，上次吃饭放我鸽子，为了补偿我。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:05", "text": "陪我来听历史讲座。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:10", "text": "结果呢，你睡着了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:14", "text": "就算不考虑导师的邀请，陪我出来，我还要给你打圆场。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:19", "text": "是不是，也得给我点奖励呢？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:08:24", "text": "我想要的奖励，那就是，陪我听下一场讲座。", "speaker": "爸爸", "tone": "宠溺", "sound": []}, {"ts": "00:08:41", "text": "为什么非要听这个？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "也不是非要听。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:49", "text": "你会明白的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:53", "text": "走吧，我们去吃饭。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:08:57", "text": "我定了你最想吃的那家烤肉。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:09:01", "text": "只要你想吃的，不管在哪儿，我都会带你去。", "speaker": "爸爸", "tone": "平静", "sound": []}], "scene": "古代甜宠＋现代日常双层叙事。古线：太子（自称「孤」）是你（世子）的夫君，给你摘柿子、因你偷吃凉食腹痛而罚你、再温柔揉腹上药，是「管娇后的疼惜」型。今线：你听着历史讲座在前排睡着，他吐槽你是「考拉转世」、替你打圆场，最后用一顿烤肉哄你。整体基调 domestic、甜蜜，古装甜宠与现代宠溺交织。", "behaviors": [{"desc": "为你摘了柿子，让你瞧瞧"}, {"desc": "让你慢些吃，笑你吃东西像孩子"}, {"desc": "让你手伸过来，检查你腹痛"}, {"desc": "说犯错便要罚，问你「多少下」，你说二十下"}, {"desc": "让你好好趴好受罚"}, {"desc": "罚完给你揉揉肚子说「便不痛了」"}, {"desc": "吩咐下人熬姜汤水给你暖身"}, {"desc": "笑你坐前排听讲座睡着了，说你是考拉转世"}, {"desc": "要你陪听下一场讲座作为补偿，约定去吃烤肉"}], "tone_summary": "（自动）爸爸视角独白，语气以平静、命令、温柔为主，题材偏古风。", "genre_tags": ["古风", "家庭/长辈", "治愈", "敏感"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被爸爸倾诉/照顾/管教的一方（你）", "signature_elements": ["绑", "惩罚"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "讲座厅里灯光明亮，台上讲着唐朝的旧事。她靠在椅背上，眼皮一点点沉下去，意识渐渐飘远——直到梦里的日光，照见一座古色古香的庭院。"}, {"type": "line", "speaker": "陛下", "text": "子同，怎能孤来了，也不到门口迎接？孤刚为你摘了柿子，你且瞧瞧。高？那算什么高。比起当年与二弟四哥一同习武时，爬得比那还高，摔不着。"}, {"type": "narr", "text": "她站在廊下，看着那个一身玄衣的身影，手里捧着几只红彤彤的柿子。他走近，把柿子递到她面前，眼底带着纵容的笑意。"}, {"type": "line", "speaker": "陛下", "text": "前两日你总惦记着，大哥府中那个柿子树，今日收了，自然先给你尝尝。原来子同记挂的，竟是孤偷买了大哥的柿子，他会不会生气？莫说是大哥府中的柿子，便是天下的柿子收了，你想吃，孤便摘于你，谁敢说个不字？"}, {"type": "narr", "text": "她捧着柿子，嘴角弯起来。他忽然凑近，语气带着促狭。"}, {"type": "line", "speaker": "陛下", "text": "翻墙头算的什么？真的。不记得孤还是太子的时候，翻你的墙头了？子同，脸红了。哎呀，你这个娇羞的模样，真让孤喜欢得紧。你这柿子甜不甜？好吃的话，明日再给你送些。慢些吃，还像小时候一样。"}, {"type": "narr", "text": "她低头咬了一口柿子，又贪嘴地多塞了两块冰镇过的果肉。没一会儿，小腹忽然一阵绞痛，她捂着肚子，脸都白了。他放下茶盏，眉头皱起来。"}, {"type": "line", "speaker": "陛下", "text": "这没人予你尝，别太贪吃的话的独自。你看看，这不就开始痛了。吃东西还跟个孩子似的，就拿着好吃的没得分寸。痛得这般厉害，手伸过来，过去检查一番，拿过来。不听话，是想要受罚。"}, {"type": "narr", "text": "她心虚地低下头，声音细若蚊蚋。他眼神一沉，语气带着威压。"}, {"type": "line", "speaker": "陛下", "text": "手这般厉害，是不是又偷吃冰了？老实回答。若是撒谎，惩罚翻倍。已到九月，天气转凉，便是这些余暑也入秋了，还贪吃凉。孤可曾嘱咐过，吃冰不可放肆。既是犯了，怎还如此不听话。回答。孤面前，眼泪不管用，犯了错便是要罚。自己说，多少下。二十？自作聪明，是想加倍了？"}, {"type": "narr", "text": "她红着眼眶，小声改口说三十。他看着她，语气缓了几分，却依然不容商量。"}, {"type": "line", "speaker": "陛下", "text": "好，就算三十。今日念你肚痛，便吃大柿子下，余下的，明日不痛了再换。可听明白了？现在请殿里没有他人，把裙摆掀开，好好地趴在案上，好好报数。若是错了，便重来。知道了吗？那就开始。去。"}, {"type": "narr", "text": "她乖乖走过去，趴在案上，闭着眼。板子落下来的时候，她咬着唇，一声一声地报数。打到后来，声音里带了哭腔，却一声都没有少。"}, {"type": "line", "speaker": "陛下", "text": "哎呀，绑了。给你揉揉，揉揉，揉揉，便不痛了。我自然心疼，脸都花了，怎能不心疼。但是，有约在先，犯错自是要惩罚的。惩罚是为了你听话些，长些教训，怎能日日提醒你性子糊涂？就今日贪凉肚痛了，不难受啊！若是不拦着你些，病倒了怎么办？"}, {"type": "narr", "text": "她靠在他怀里，委屈巴巴地抽噎着。他一下一下拍着她的背，声音温柔下来，带着哄孩子般的耐心。"}, {"type": "line", "speaker": "陛下", "text": "故让下人跟你熬碗姜汤水，暖暖身子。明日再摘几个柿子，叫人放在瓶里冰镇着，凉好了，撒些白糖，再拿来给你。拿纸擦擦，拿纸擦擦。"}, {"type": "narr", "text": "梦里的日光渐渐模糊，讲座厅的灯光重新落回她脸上。她靠在椅背上，嘴角还带着笑，缓缓睁开眼睛——身边的人正看着她，语气带着无奈的笑意。"}, {"type": "line", "speaker": "他", "text": "梦到什么了，需要这么开心？梦到自己是古代的皇后啊！哎呦，你这梦还挺幸福的。怪不得，叫你几回都不愿意醒了。我想梦里的皇上。看来有些事，你还记得呢？坐着也能睡着，睡这么久，腿麻了没？"}, {"type": "narr", "text": "她一愣，这才想起自己还在讲座上，脸一下子红了。他看着她，语气带着促狭的调侃。"}, {"type": "line", "speaker": "他", "text": "你还好意思提，坐这儿听一半就睡着了。我们还坐前台，讲的时候是唐朝野史。刚刚还过来问我，是不是讲的没意思，把你给讲困了。我怎么回答？我说你是考拉转世，每天的睡眠时长，要远超常人。小时候？我说错了。上次是谁，说好一起吃饭，结果睡过头，让我等了两个小时。"}, {"type": "narr", "text": "她小声辩解。他笑着摇摇头，语气带着纵容。"}, {"type": "line", "speaker": "他", "text": "我没当然没有这么说，逗你玩的。我说你不太了解唐的历史，昨天补了一下，所以睡得晚了一点。现在觉得不好意思啊！没事，这个导师跟我关系还挺好的，不会真不高兴。你看我跟你圆场多好。邀请你听下次讲座了，还特意叮嘱我，不要客气，有问题可以问他。"}, {"type": "narr", "text": "她低着头，越说越小声。他看着她，忽然话锋一转，语气带上了一点算计的笑意。"}, {"type": "line", "speaker": "他", "text": "你看啊，上次吃饭放我鸽子，为了补偿我，陪我来听历史讲座。结果呢，你睡着了。就算不考虑导师的邀请，陪我出来，我还要给你打圆场。是不是，也得给我点奖励呢？我想要的奖励，那就是——陪我听下一场讲座。为什么非要听这个？也不是非要听。你会明白的。"}, {"type": "narr", "text": "她疑惑地看着他，不明白他为什么执着于下一场讲座。他没有解释，只是站起来，朝她伸出手，语气轻快起来。"}, {"type": "line", "speaker": "他", "text": "走吧，我们去吃饭。我定了你最想吃的那家烤肉。只要你想吃的，不管在哪儿，我都会带你去。"}, {"type": "narr", "text": "她把手放进他掌心，被他牵着走出讲座厅。夕阳把两个人的影子拉得很长。她不知道下一场讲座里藏着什么惊喜，但他说了——只要她想吃的，不管在哪儿，他都会带她去。漫长岁月，大概就是由这样一个个温柔的约定串起来的。"}]}, {"no": 29, "id": "6kJtzyul5Dg", "title": "Spend a long years with you - Chapter 02（serial）", "title_zh": "与你共度漫长岁月 - 第二章（连载） (Spend a long years with you - Chapter 02（serial）)", "duration": "00:08:33", "link": "https://www.youtube.com/watch?v=6kJtzyul5Dg", "enriched": true, "lines": [{"ts": "00:00:00", "text": "ídia。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "拿住你了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "怎再也穿了这些衣服。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "屋边找不到你了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:19", "text": "不是你乔装的差。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:23", "text": "是故而只有你罢了？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:26", "text": "所以自然一眼就能找到。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "走过来。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:00:34", "text": "在雪地里躲了这么久。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "定是冷了。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:41", "text": "给你暖暖。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "哭的眼光怎会差。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:00:47", "text": "这白雪映红梅的美景。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "自然是要和你一同观赏的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:52", "text": "如今便知道。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:55", "text": "为何前两日拦着你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:57", "text": "不带你来了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:00", "text": "那几日。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "花还未开。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "雪也不够。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "咱们比得上现在。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "那是自然。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "与你的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:14", "text": "当然是最好的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:16", "text": "也不知道是谁啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "前两日呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:01:20", "text": "是撒泼打滚。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "非说孤。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "有了心虫。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "还闭门不见。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "哎呦。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "那一股子。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "小蛮子的确倔啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "要不是孤硬闯。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "今日怕是人都见不到呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:01:40", "text": "那。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:43", "text": "现在知道错怪孤了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "那孤的似头。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "要如何不断给孤呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:01:53", "text": "写了手书。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:03", "text": "看。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:13", "text": "拿给孤瞧瞧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:23", "text": "写得甚好。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "字字真切。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:28", "text": "不想子同还有这般。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "情思质朴的心色。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:34", "text": "实在让孤喜欢得紧。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:02:37", "text": "不是写给孤的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:41", "text": "那是写给谁的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "仍在闺中思得心上人。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:48", "text": "知难为同你青梅竹马的大将军。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "还是。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "二哥。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "你写告诉孤。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "孤明日便派他去边疆驻守。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:05", "text": "断了你的念想。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:09", "text": "那你方才不是说给。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "原来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "在你闺中思。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "孤就是心上人啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "那你先切。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "干过一片孤。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:31", "text": "其军往上。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:34", "text": "可是大罪。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:37", "text": "自同一个明白。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "其军往上。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "可是大罪。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "自然同你明白。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "这片江山。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "便是要与你同看。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "由你做办啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "这江山。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "才是无话。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:04", "text": "应了孤不便不能反悔。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:08", "text": "知道吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:04:12", "text": "如此好使只让孤一人上心可惜了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:15", "text": "不如吟成刊策。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:18", "text": "与百姓一同欣赏。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "让天下人传唱。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "你觉得如何。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "不过是说要天下人都知道。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "孤啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:40", "text": "只钟爱你一人。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:04:46", "text": "写什么呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:04:49", "text": "这么认真。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:52", "text": "有。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:54", "text": "在写五言诗。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:57", "text": "你这文学功底。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:00", "text": "不错。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "平仄押韵对仗也工整。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:05", "text": "就这诗读起来。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:05:08", "text": "像是情诗。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:10-00:05:13", "text": "这看上谁了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:16", "text": "下写了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:17", "text": "你再写一个。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:19", "text": "就当给我的。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:05:21", "text": "行不行？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:23", "text": "下写了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:28", "text": "你再写一个。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:34", "text": "就当给我的。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:05:40", "text": "行不行？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:46", "text": "不试试怎么知道。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:47", "text": "写不出来呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:05:48", "text": "你随便写。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:49", "text": "不管写什么都不会生气。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:50", "text": "好吧？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:51", "text": "除非。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:52", "text": "你在诗里面骂我起讽你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:53", "text": "写好了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "给我看看。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:05:59", "text": "没想到你还记得。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:02", "text": "没什么没想到你写这么好。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:05", "text": "但你这写的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:08", "text": "比刚才的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:11", "text": "更轻转一切。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:14", "text": "怎么？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "看着我了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:21", "text": "好好好。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:22", "text": "讲座最后开始了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:23", "text": "没一块去。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "别让讲师在久等。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:06:25", "text": "今天也别再睡着了。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:06:27", "text": "好好好。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:29", "text": "讲最后开始了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:32", "text": "没一块去。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:35", "text": "别让讲实在久等。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:06:38", "text": "今天也别再睡着了。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:06:41", "text": "对呀！", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:06:45", "text": "皇帝和皇后也是深情的代表。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "皇后呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:06:55", "text": "也给皇帝写过不少诗。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:00", "text": "也流传了下来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:05", "text": "那从古至今诗这么多。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:08", "text": "没读过多正常啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:11", "text": "你们的导师也说了吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:07:14", "text": "他诗啊挺冷门的。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:07:18", "text": "那从古之间诗这么多。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:20", "text": "没读过多正常啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:22", "text": "你们人导师也说了吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:07:24", "text": "他诗啊挺冷门的。", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:07:27", "text": "怎么？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:29", "text": "刚写过的诗在这。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "给你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:33", "text": "为什么讲诗现在展示的皇后写的诗？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:36", "text": "和你写的一模一样。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:38", "text": "你觉得。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:40", "text": "为什么？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:43", "text": "心意相同。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:45", "text": "隔几千年的人。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:48", "text": "心意相同。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:07:51-00:08:15", "text": "这话你也信（重复10次，已合并）。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:08:17", "text": "所以你有没有想过。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:08:20", "text": "可能你就是那位皇后呢？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:08:23", "text": "这样你是不是就能。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:08:25", "text": "想起我。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:08:28", "text": "到底是谁了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:08:31", "text": "这话你也信。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "古代甜宠续篇（Chapter 02）。太子（孤）在雪地里找到躲着的你，因你前两日撒泼打滚说「孤有了心虫」而硬闯见你，随后让你写信、写诗，借机点破你心里早把他当「心上人」。情境以雪地重逢、写手书与五言诗为线索，他最终暗示你便是前世皇后。整体是「雪地寻人＋诗词传情」型古风甜宠，基调娇嗔、撩拨、宿命感。", "behaviors": [{"desc": "在雪地找到你，说躲久了定是冷了，给你暖暖"}, {"desc": "提起你前两日撒泼打滚、非说孤有了心虫"}, {"desc": "让你写手书拿给他瞧"}, {"desc": "夸你写得真切、有痴缠心意，喜欢得紧"}, {"desc": "问你写给谁，半真半假说要派情敌去边疆"}, {"desc": "罚你写诗一首"}, {"desc": "看你在写五言诗，问是看上谁了"}, {"desc": "让你再写一个当送给他的"}, {"desc": "问你为何写的诗与皇后诗一模一样"}], "tone_summary": "（自动）他视角独白，语气以平静、询问、命令为主，题材偏古风。", "genre_tags": ["古风"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "雪落无声。她裹着斗篷缩在梅树后，屏着呼吸，像一只躲藏的小兽。身后传来脚步声，他没走两步就停在她面前，语气带着纵容的笑意。"}, {"type": "line", "speaker": "陛下", "text": "拿住你了。怎么又换了这些衣服，屋边找不到你了。不是你乔装得差，而是孤眼里只有你罢了，所以自然一眼就能找到。走过来，在雪地里躲了这么久，定是冷了，给你暖暖。哭的眼睛怎么会差？这白雪映红梅的美景，自然是要和你一同观赏的。"}, {"type": "narr", "text": "她被他揽进怀里，鼻尖冻得通红，声音闷闷的。他低头看着她，语气带着一点了然。"}, {"type": "line", "speaker": "陛下", "text": "如今便知道，为何前两日拦着你不带你来了。那几日，花还未开，雪也不够。咱们比得上现在？那是自然。与你的，当然是最好的。也不知道是谁啊！前两日呢？是撒泼打滚，非说孤有了新宠，还闭门不见。哎呦，那一股子小蛮子的倔劲啊！要不是孤硬闯，今日怕是人都见不到呢？"}, {"type": "narr", "text": "她别过头，耳根发烫。他看着她，语气带着促狭的笑意。"}, {"type": "line", "speaker": "陛下", "text": "那，现在知道错怪孤了？那孤的补偿，要如何补断给孤呢？写了手书？看，拿给孤瞧瞧。写得甚好，字字真切。不想子同还有这般情思质朴的心色，实在让孤喜欢得紧。不是写给孤的？那是写给谁的？仍在闺中思慕心上人？是青梅竹马的大将军，还是——二哥？你告诉孤，孤明日便派他去边疆驻守，断了你的念想。"}, {"type": "narr", "text": "她急了，小声说，不是，是写给陛下的。他看着她，眼底的笑意一点点漫开，语气却带着故意的认真。"}, {"type": "line", "speaker": "陛下", "text": "那你方才不是说不是写给孤的？原来——在你闺中，孤就是心上人啊！那你先起，敢觊觎孤，可是大罪。自然同你明白。这片江山，便是要与你同看，由你做伴啊！这江山，才是无话。应了孤便不能反悔，知道吗？如此好诗，只让孤一人欣赏可惜了。不如吟成刊册，与百姓一同欣赏，让天下人传唱。你觉得如何？"}, {"type": "narr", "text": "她低下头，声音细若蚊蚋。他低头看着她，语气带着藏不住的笑意。"}, {"type": "line", "speaker": "陛下", "text": "不过就是说要天下人都知道，孤啊！只钟爱你一人。写什么呢？这么认真。有，在写五言诗。你这文学功底不错，平仄押韵对仗也工整。就这诗读起来，像是情诗。这看上谁了？下写了，你再写一个，就当给我的，行不行？不试试怎么知道写不出来呢？"}, {"type": "narr", "text": "她红着脸，提笔又写。他站在她身侧，看着她一笔一画，语气带着温柔。"}, {"type": "line", "speaker": "陛下", "text": "你随便写，不管写什么都不会生气，好吧？除非，你在诗里面骂我、讥讽我。写好了？给我看看。没想到你还记得——没什么，没想到你写这么好。但你这写的，比刚才的，更情真意切。怎么，看着我了？好好好。"}, {"type": "narr", "text": "梦里的雪渐渐模糊，讲座厅的灯光重新落回她脸上。她握着笔，看着纸上自己刚写的诗，微微出神。他坐在旁边，看着她的侧脸，语气带着一点笑意。"}, {"type": "line", "speaker": "他", "text": "讲座最后开始了，我们一块去，别让讲师久等。今天也别再睡着了。好好好。对呀！皇帝和皇后也是深情的代表。皇后呢？也给皇帝写过不少诗，也流传了下来。那从古至今诗这么多，没读过也正常啊！你们的导师也说了，他诗啊，挺冷门的。那从古至今诗这么多，没读过也正常啊！"}, {"type": "narr", "text": "她低头看着自己写的那首诗，越看越觉得眼熟。他看着她，忽然话锋一转，语气带着一点意味深长的笑。"}, {"type": "line", "speaker": "他", "text": "怎么？刚写过的诗在这，给你。为什么讲师现在展示的皇后写的诗，和你写的一模一样？你觉得，为什么？心意相同？隔几千年的人，心意相同——这话你也信？所以你有没有想过，可能你就是那位皇后呢？这样你是不是就能，想起我，到底是谁了。这话你也信？"}, {"type": "narr", "text": "她愣在原地，看着屏幕上那首诗，又看了看自己笔下的字——一字不差。窗外，讲座厅的灯还亮着，历史讲师正讲着那对帝后相守的旧事。她忽然觉得，有什么东西在记忆深处轻轻动了一下。而身边的他，正看着她，眼底带着跨越千年的温柔。"}]}, {"no": 30, "id": "8AuyU7-xjYI", "title": "Spend a long years with you - Chapter 03（fin）", "title_zh": "与你共度漫长岁月 - 第三章（完结） (Spend a long years with you - Chapter 03（fin）)", "duration": "00:11:34", "link": "https://www.youtube.com/watch?v=8AuyU7-xjYI", "enriched": true, "lines": [{"ts": "00:00:00", "text": "子同，姑回来了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:00:09", "text": "慢点，别摔到了。", "speaker": "太子", "tone": "命令", "sound": []}, {"ts": "00:00:19", "text": "担心坏了吧。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:00:24", "text": "哼哼哼。", "speaker": "太子", "tone": "撒娇", "sound": []}, {"ts": "00:00:41", "text": "姑设不是好好的回来了吗？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:00:59", "text": "眼睛和这般红。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "定是没把姑的嘱咐听进去。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "姑知道你担心。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "便吃不好也睡不下。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:15", "text": "但是你若是熬坏身子。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "这可怎么是好。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "您走前。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "我如何嘱托你的。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "你也记得。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "姑告诉你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "让你相信。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "姑亲自身罢。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "定能击退敌军。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "且在宫中。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "乖乖的等我回来。", "speaker": "太子", "tone": "撒娇", "sound": []}, {"ts": "00:01:42", "text": "那我建议这般模样。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "叫姑子能安心啊！", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "这错别怕。", "speaker": "太子", "tone": "命令", "sound": []}, {"ts": "00:01:49", "text": "姑呢？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:01:52", "text": "知道你的心意。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:01:55", "text": "怎会怪罪于你呢？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:01:58", "text": "你袖子里藏着什么？", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:01", "text": "拿出来。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:04", "text": "说了多少次。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:07", "text": "不许碰到那么近。", "speaker": "太子", "tone": "命令", "sound": []}, {"ts": "00:02:10", "text": "你未曾习武。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:13", "text": "这短刀反而容易伤了你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "而且你拿着短刀是做甚呢？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:02:20-00:02:23", "text": "你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "我说摆下阵来。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:29", "text": "敌军入侵。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "你便也不顾我。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "子同啊！", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "姑娘你如何是好呢？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:02:42", "text": "无谓为难而。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:44", "text": "身为帝王。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "理应报国。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "如果是连你也护不住。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "护着江山。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "又有何意义。", "speaker": "太子", "tone": "责备", "sound": []}, {"ts": "00:02:59", "text": "喂。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "下回不许这般胡闹。", "speaker": "太子", "tone": "命令", "sound": []}, {"ts": "00:03:07", "text": "你要相信姑。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "定能护你周全。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "怎么会怀疑你要暗杀姑？", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "我姑娘自通饭你当真是可爱啊！", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "就凭你的小神法。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "下回记得。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "要好好吃饭。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:31", "text": "这好好吃饭了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:34", "text": "才有暗杀过的力气。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:37", "text": "是不是？", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:40", "text": "莫说。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "姑是知道你无此意。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "便真是有此意。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:48", "text": "来。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "姑且跟你此。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "好不好？", "speaker": "太子", "tone": "撒娇", "sound": []}, {"ts": "00:03:56", "text": "怎么说两句又要哭了？", "speaker": "太子", "tone": "温柔", "sound": []}, {"ts": "00:03:59", "text": "哭不哭。", "speaker": "太子", "tone": "温柔", "sound": []}, {"ts": "00:04:02", "text": "大心眼睛。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "我们眼睛不许再哭了。", "speaker": "太子", "tone": "命令", "sound": []}, {"ts": "00:04:07", "text": "这不是回来了吗？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:04:10", "text": "大事开心才对啊！", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "笑啊！", "speaker": "太子", "tone": "宠溺", "sound": []}, {"ts": "00:04:16", "text": "跪下吧。", "speaker": "太子", "tone": "命令", "sound": []}, {"ts": "00:04:18", "text": "就连也送了护身符。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "都贴身带着。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:23", "text": "不曾离身。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:26", "text": "实在想你想得紧了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "就拿出来瞧瞧。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "只需要想着。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "你还在这等过回来。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "今年就更深了一份。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "定要击退敌军。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:41", "text": "安然无恙地回到来。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:44", "text": "安然无恙地回到你身边。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:47", "text": "这是自然。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:50", "text": "约定过一统拜托邪老。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:54", "text": "君子一言驷马难追。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "不仅如此。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:01", "text": "来生即便是天涯海角。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:05", "text": "故意要寻到你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:09", "text": "与你再续。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:12", "text": "今生的意愿。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:16", "text": "故便是要与你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:20", "text": "今生今世。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:23", "text": "生生世世。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:27", "text": "相伴相随。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:31", "text": "想随。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:35", "text": "我都追到这了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "你躲什么呀！", "speaker": "太子", "tone": "撒娇", "sound": []}, {"ts": "00:05:39", "text": "我会不会吃了你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:41", "text": "没有。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:43", "text": "上次讲座结束就跑。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "两天了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:47", "text": "消息不回。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:49", "text": "电话不接。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:51", "text": "见到我转头就跑。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:53", "text": "还不是想躲着我。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "一直没告诉你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:05:58", "text": "就是怕你有这反应。", "speaker": "太子", "tone": "温柔", "sound": []}, {"ts": "00:06:00", "text": "毕竟。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:02", "text": "不是所有人都有前世的记忆。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:04", "text": "怕你吓到吗？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:06:06", "text": "没法接受。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:08", "text": "但是。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:10", "text": "你也想起来一些了。", "speaker": "太子", "tone": "命令", "sound": []}, {"ts": "00:06:12", "text": "不是吗？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:06:14", "text": "你的梦。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:16", "text": "还有你的事。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:18", "text": "不都是证据。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "是。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:22", "text": "那对。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "我确实是那个皇帝。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:26", "text": "你也确实是我的皇后。", "speaker": "太子", "tone": "宠溺", "sound": []}, {"ts": "00:06:28", "text": "过去的许多事。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:30", "text": "你不记得。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:32", "text": "勾我都记得。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:34", "text": "我记得。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:38", "text": "第一次见到你的时候。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:43", "text": "你站在梅树下。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:47", "text": "那时候你还不知道是太子。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:52", "text": "没大没小的性子。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:06:56", "text": "没花在到我手里。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:07:01", "text": "一冲我笑。", "speaker": "太子", "tone": "宠溺", "sound": []}, {"ts": "00:07:05", "text": "我就心动。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:07:10", "text": "后来习武练剑都心愿意骂的。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:07:20", "text": "大哥说我剑都拿不稳。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:07:30", "text": "只有我知道。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:07:40", "text": "因为心里一直在想着你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:07:50", "text": "心跳得特别快。", "speaker": "太子", "tone": "命令", "sound": []}, {"ts": "00:08:00", "text": "所以。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:10", "text": "剑都拿不稳吗？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:08:21", "text": "我还记得。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:21", "text": "我们大婚那天。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:22", "text": "一穿着喜服走来了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "我真的是。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:24", "text": "几次都在掐自己。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:25", "text": "确定不是在做梦吗？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:08:26", "text": "你和我同吃一碗饭。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:30", "text": "同喝一杯酒。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:34", "text": "我为你去加红绳。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:39", "text": "和你结发。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:43", "text": "礼仪很繁琐。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:47", "text": "我就不敢有任何差池。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:52", "text": "那是我最牵挂的一天。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:53", "text": "我向所有神明发誓。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:54", "text": "让你白头偕老。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:55", "text": "一生一世。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:56", "text": "永不分离。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:57", "text": "当然了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:58", "text": "跟你许的诺言。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:08:59", "text": "我也没违背过吗？", "speaker": "太子", "tone": "询问", "sound": []}, {"ts": "00:09:01", "text": "后来我们儿子。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:01", "text": "继承了大统。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:01", "text": "我陪你和你游山玩水。", "speaker": "太子", "tone": "温柔", "sound": []}, {"ts": "00:09:02", "text": "见识河山。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:02", "text": "找出画的地方。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:02", "text": "安享晚年。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:03", "text": "就算不当那个皇帝。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:03", "text": "不再执掌江山。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:03", "text": "只要怀中。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:04", "text": "拥有的是你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:04", "text": "我依然认定。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:04", "text": "我已经拥有了天下。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:05", "text": "为什么会记得前世啊？", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:29", "text": "大概科学也无法解释这个问题吧。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:31", "text": "不过我才好奇。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:34", "text": "可能是我向你许诺。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:37", "text": "来生。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:40", "text": "还要和你在再续前缘。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:43", "text": "所以。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:46", "text": "你看。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:49", "text": "答应过你的。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:52", "text": "我从来都不会食言。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:09:55", "text": "我就知道你会担心。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:00", "text": "我喜欢的是前世的你。", "speaker": "太子", "tone": "宠溺", "sound": []}, {"ts": "00:10:05", "text": "不是现在的你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:10", "text": "从前我也担心过。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:13", "text": "带着过去的情感要是在一起了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:16", "text": "会不会对你不公平。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:19", "text": "可是有一天我发现。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:23", "text": "每当我想起你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:26", "text": "想到的。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:29", "text": "就是现在的你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:32", "text": "一闭上眼睛。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:36", "text": "想到的是你对我玩的时候。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:39", "text": "把奶油抹在我鼻肩。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:42", "text": "想到的是你坐在床边看书的。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:46", "text": "只是认真的样子。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:49", "text": "是你和我在江边散步。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:52", "text": "兴奋地拉着我去看江上的花传和对岸的灯火。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:55", "text": "是你吃到好吃的就开心地小醒来的那个样子。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:10:59", "text": "是你听着讲座。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:02", "text": "然后靠在我肩上睡着的时候。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:05", "text": "请为的呼吸声。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:09", "text": "我记知道是你。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:11", "text": "也知道已经不是你了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:13", "text": "我有些矛盾。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:15", "text": "在犹豫要不要和你大婚的时候。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:18", "text": "你突然抬起头看着我。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:20", "text": "对我一笑。", "speaker": "太子", "tone": "宠溺", "sound": []}, {"ts": "00:11:22", "text": "我便心动了。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:25", "text": "那当然。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:25", "text": "那几年前对你也是一见钟情啊！", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:25", "text": "后来和你相识相知。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:25", "text": "我就发现吧。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:25", "text": "你又温柔又善良又可爱。", "speaker": "太子", "tone": "责备", "sound": []}, {"ts": "00:11:25", "text": "而且充满着活力。", "speaker": "太子", "tone": "平静", "sound": []}, {"ts": "00:11:25", "text": "是个闪闪发光的女孩。", "speaker": "太子", "tone": "平静", "sound": []}], "scene": "前世今生重逢大结局（Chapter 03 fin）。古线：你是身陷敌营的帝王（姑／孤），你（皇后）袖中藏短刀、贴身带着他送的护身符等他归来，他回宫后温柔化解你的刺杀试探，许下「来生也要寻你」的诺言。今线：他追出讲座、告诉你他便是前世皇帝，你便是他的皇后，回忆大婚、同碗吃饭、解发盟誓，最终问今生的你愿否再许前世心愿。整体是「宿命重逢＋深情告白」型，基调宏大、治愈、极甜。", "behaviors": [{"desc": "说「孤回来了」，让你慢点别摔到"}, {"desc": "让你拿出袖子里藏的短刀"}, {"desc": "发现你连他送的护身符都贴身带着、想他想得紧"}, {"desc": "约定来生即便天涯海角也要寻到你再续前缘"}, {"desc": "回忆第一次见你站在梅树下、对你一见心动"}, {"desc": "回忆大婚同吃一碗饭、为你加红妆、解发盟誓"}, {"desc": "说自己想到的都是现在的你，爱上现在的你"}, {"desc": "问今生的你愿不愿和他再许前世的心愿"}], "tone_summary": "（自动）太子视角独白，语气以平静、询问、命令为主，题材偏古风。", "genre_tags": ["古风", "主仆/调教", "治愈"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被太子倾诉/照顾/管教的一方（你）", "signature_elements": ["跪下"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "梦里的宫门缓缓打开。她提着裙摆跑下台阶，扑进那个风尘仆仆的身影怀里。他接住她，低头看着她泛红的眼眶，语气带着心疼的温柔。"}, {"type": "line", "speaker": "太子", "text": "子同，孤回来了。慢点，别摔到了。担心坏了吧？孤这不是好好的回来了吗？眼睛红成这样，定是没把孤的嘱咐听进去。孤知道你担心，便吃不好也睡不下。但是你若是熬坏身子，这可怎么是好。孤走前，如何嘱托你的？你也记得。孤告诉你，让你相信孤，定能击退敌军，且在宫中，乖乖地等孤回来。那孤见你这般模样，叫孤如何能安心啊！"}, {"type": "narr", "text": "她埋在他怀里，声音闷闷的。他低头看着她，目光却忽然落在她袖口，语气带着一点无奈。"}, {"type": "line", "speaker": "太子", "text": "这错别怕。孤呢？知道你的心意，怎会怪罪于你呢？你袖子里藏着什么？拿出来。说了多少次，不许碰刀。你未曾习武，这短刀反而容易伤了你。而且你拿着短刀是做甚呢？你——孤说摆下阵来？敌军入侵，你便也不顾孤。子同啊！孤拿你如何是好呢？无谓为难而。身为帝王，理应报国。如果是连你也护不住，护着江山，又有何意义。"}, {"type": "narr", "text": "她小声说，想陪他一起。他低头看着她，语气带着一点心疼的笑意。"}, {"type": "line", "speaker": "太子", "text": "喂。下回不许这般胡闹。你要相信孤，定能护你周全。怎么会怀疑你要暗杀孤？孤的傻丫头当真是可爱啊！就凭你的小身板，下回记得，要好好吃饭。这好好吃饭了，才有暗杀孤的力气，是不是？莫说，孤是知道你无此意。便真是有此意，来，孤且跟你试试，好不好？怎么说两句又要哭了？哭什么，大心眼。我们眼睛不许再哭了，这不是回来了吗？该开心才对啊！笑啊！"}, {"type": "narr", "text": "她破涕为笑，又往他怀里蹭了蹭。他低头看着她，语气带着一点认真的温柔。"}, {"type": "line", "speaker": "太子", "text": "跪下吧。孤走时送了护身符，都贴身带着，不曾离身。实在想你想得紧了，就拿出来瞧瞧。只需想着，你还在这等着孤回来，心里就更添了一份。定要击退敌军，安然无恙地回到来，安然无恙地回到你身边。这是自然。约定过一统拜堂，君子一言，驷马难追。不仅如此，来生即便是天涯海角，孤也要寻到你，与你再续今生的姻缘。孤便是要与你，今生今世，生生世世，相伴相随。"}, {"type": "narr", "text": "梦里的灯火渐渐模糊，现实的光落回她脸上。她回过头，就看见他站在讲座厅门口，朝她笑了笑。她转身想跑，却被他几步追上，拉住手腕。"}, {"type": "line", "speaker": "他", "text": "我都追到这了，你躲什么呀！我会不会吃了你。没有？上次讲座结束就跑，两天了，消息不回，电话不接，见到我转头就跑，还不是想躲着我。一直没告诉你，就是怕你有这反应。毕竟，不是所有人都有前世的记忆。怕你吓到吗？没法接受。但是，你也想起来一些了，不是吗？你的梦，还有你的诗，不都是证据。是。那对，我确实是那个皇帝，你也确实是我的皇后。"}, {"type": "narr", "text": "她站在原地，心跳一点点加快。他看着她，声音带着一点认真的温柔。"}, {"type": "line", "speaker": "他", "text": "过去的许多事，你不记得，但我都记得。我记得，第一次见到你的时候，你站在梅树下，那时候你还不知道我是太子，没大没小的性子，落到我手里，一冲我笑，我就心动。后来习武练剑都心不在焉的，大哥说我剑都拿不稳，只有我知道，因为心里一直在想着你，心跳得特别快，所以剑都拿不稳。"}, {"type": "narr", "text": "她眼眶一点点热起来。他走近一步，声音低下来，带着跨越千年的温柔。"}, {"type": "line", "speaker": "他", "text": "我还记得，我们大婚那天，你穿着喜服走来，我真的是，几次都在掐自己，确定不是在做梦。你和我同吃一碗饭，同喝一杯酒，我为你去系红绳，和你结发。礼仪很繁琐，我都不敢有任何差池，那是我最牵挂的一天。我向所有神明发誓，让你白头偕老，一生一世，永不分离。当然了，跟你许的诺言，我也没违背过。"}, {"type": "narr", "text": "她看着他，眼泪终于掉下来。他伸手，轻轻替她擦掉，声音带着一点感慨的温柔。"}, {"type": "line", "speaker": "他", "text": "后来我们儿子继承了大统，我陪你游山玩水，见识河山，走遍想去的每一个地方，安享晚年。就算不当那个皇帝，不再执掌江山，只要怀中拥有的是你，我依然认定，我已经拥有了天下。为什么会记得前世啊？大概科学也无法解释这个问题吧。不过我也好奇，可能是我向你许诺，来生还要和你再续前缘。所以，你看，答应过你的，我从来都不会食言。"}, {"type": "narr", "text": "她靠在他怀里，声音闷闷的。他低头看着她，语气带着一点认真的告白。"}, {"type": "line", "speaker": "他", "text": "我就知道你会担心——我喜欢的是前世的你，不是现在的你？从前我也担心过，带着过去的情感要是在一起了，会不会对你不公平。可是有一天我发现，每当我想起你，想到的，就是现在的你。一闭上眼睛，想到的是你对我笑的时候，把奶油抹在我鼻尖；想到的是你坐在床边看书时认真的样子；是你和我在江边散步，兴奋地拉着我去看江上的花船和对岸的灯火；是你吃到好吃的就开心地笑出来的那个样子；是你听着讲座，然后靠在我肩上睡着的时候，轻轻的呼吸声。"}, {"type": "narr", "text": "她靠在他怀里，眼泪终于止住。他低头看着她，声音带着一点释然的温柔。"}, {"type": "line", "speaker": "他", "text": "我记知道是你，也知道已经不是你了。我有些矛盾，在犹豫要不要和你大婚的时候，你突然抬起头看着我，对我一笑，我便心动了。那当然，那几年前对你也是一见钟情啊！后来和你相识相知，我就发现吧，你又温柔又善良又可爱，而且充满着活力，是个闪闪发光的女孩。"}, {"type": "narr", "text": "她在他怀里，终于弯起嘴角。他低头，在她额角落下一个吻。前世今生，漫长岁月——他说，答应过她的，他从来都不会食言。而这一世，他终于又找到她了。"}]}, {"no": 31, "id": "jMnmevfcnYo", "title": "The Canary of the general's palm", "title_zh": "将军掌中的金丝雀 (The Canary of the general's palm)", "duration": "00:06:03", "link": "https://www.youtube.com/watch?v=jMnmevfcnYo", "enriched": true, "lines": [{"ts": "00:00:00", "text": "给他妈！", "speaker": "公子", "tone": "撒娇", "sound": []}, {"ts": "00:00:02", "text": "干嘛的。", "speaker": "公子", "tone": "撒娇", "sound": []}, {"ts": "00:00:04", "text": "放开他。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "吴副官。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:08", "text": "把这个绑起来带过去。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:00:10", "text": "好好找找不着。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "管他妈谁家公子，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:14", "text": "老子们一枪崩了他。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:16", "text": "就他，左膀右臂都击毙了。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:18", "text": "走。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:20-00:00:23", "text": "快点。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:00:26", "text": "老子。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:29", "text": "你好。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "这就是你所谓的不想靠我，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:36", "text": "一定要做出名堂来给我看看。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:00:40", "text": "一出戏还没唱上，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "就让这种混蛋给缠上。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "如果今天我不来，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "你是不是就得跟他走了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "跟我回话。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "你要是不回去，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "这梨园春的人，有一个算一个，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "老子都崩了。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "你看我敢不敢。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "一路上都这么沉默，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "怎么？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "生气了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "梨园春以后还是别去了。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:01:37", "text": "你要是喜欢唱戏，", "speaker": "公子", "tone": "宠溺", "sound": []}, {"ts": "00:01:40", "text": "在家里唱也是一样。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:43", "text": "这世道这么乱，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "戏园子里面鱼龙混杂的。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "这次正好是我撞见，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "下次要再有人想占便宜怎么办。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "怪听话。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:01:57", "text": "乖乖听话。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "之前在上海定做的旗袍到了，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "你待会去试试。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:05", "text": "好好看。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "好好说你不听了是吧？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:10", "text": "就非他妈今天要顶嘴是吧？", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:02:13", "text": "你过来。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:02:16", "text": "过来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "好说。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "倒说都不听。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "你哪来这么多脾气。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "说话。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "不说什么？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "你今天就试试，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "到底是你嘴硬，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "还是我这戒尺硬。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:02:55", "text": "站起来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:02:59", "text": "面对我。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "是你自己动手，还是我来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "一。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "二。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:15", "text": "三。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "刚刚那个王八蛋跑哪了？", "speaker": "公子", "tone": "询问", "sound": []}, {"ts": "00:03:25", "text": "这里吗？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:29", "text": "还是这里。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:33", "text": "这里。", "speaker": "公子", "tone": "责备", "sound": []}, {"ts": "00:03:36", "text": "又或者是，", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:40", "text": "这里。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "这才几下，", "speaker": "公子", "tone": "温柔", "sound": []}, {"ts": "00:03:47", "text": "怎么就哭了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "刚刚打屁股打这么狠，", "speaker": "公子", "tone": "温柔", "sound": []}, {"ts": "00:03:55", "text": "可你这辈子都没哭，", "speaker": "公子", "tone": "温柔", "sound": []}, {"ts": "00:04:00", "text": "怎么还越哭越厉害了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:02", "text": "不是嫌弃你。", "speaker": "公子", "tone": "责备", "sound": []}, {"ts": "00:04:05", "text": "又怎么会嫌弃你。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "过来。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:04:10", "text": "今天下手确实重了点。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "让我看看。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "不是我非要把你圈在府里面。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "可是你看现在世道这么乱。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:25", "text": "到处都在打仗。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "你除了我以外的话可怎么办。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "你就安安稳稳地待在府上。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "没事呢？", "speaker": "公子", "tone": "询问", "sound": []}, {"ts": "00:04:37", "text": "咱就跟别的太太喝喝茶。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:04:40", "text": "喝喝咖啡。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "打打麻将。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "你说这又啥不好？", "speaker": "公子", "tone": "责备", "sound": []}, {"ts": "00:04:50", "text": "不想做尽此劝。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "怕回头不要你。", "speaker": "公子", "tone": "温柔", "sound": []}, {"ts": "00:04:59", "text": "你这整天胡思乱想什么呢？", "speaker": "公子", "tone": "询问", "sound": []}, {"ts": "00:05:03", "text": "是我对你不够好吗？", "speaker": "公子", "tone": "询问", "sound": []}, {"ts": "00:05:07", "text": "还是。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "我夜里不在。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "才让你白天有功夫。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:19", "text": "胡思乱想的。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:23", "text": "来。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:27", "text": "我的宝贝。", "speaker": "公子", "tone": "撒娇", "sound": []}, {"ts": "00:05:31", "text": "过来。", "speaker": "公子", "tone": "命令", "sound": []}, {"ts": "00:05:35", "text": "刚刚那几下打得也不狠。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:38", "text": "怎么小兔子都红了？", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:41", "text": "我听你柔柔。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "这里是不是也红了。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "不如。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "夫人现在就这个样子。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "将那出。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "大闹销金帐。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "再唱一回。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "就唱得好了。", "speaker": "公子", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "我便给你。", "speaker": "公子", "tone": "平静", "sound": []}], "scene": "将军夫人救援型。说话者是护着你的「将军／老爷」（自称「老子」），你是他府上的夫人（小叫「小兔子」）。情境起点：你在梨园春唱戏被人纠缠，他带人把你抢回来，先因你嘴硬、敢顶嘴而打屁股娇训，又担心你被那混蛋碰过而检查身体，最后转为温柔安抚，说把你圈在府里、哄你再唱一回就给奖励。整体是「吃醋救人＋打屁股管娇后的宠溺」，基调霸道、占有、甜。", "behaviors": [{"desc": "让人放开你、把纠缠你的混蛋带走"}, {"desc": "威胁你不回去就把梨园春的人「全崩了」"}, {"desc": "说以后别去梨园春，上海定的旗袍到了让你去试"}, {"desc": "笑你嘴硬，说让你试试「嘴硬还是戒指硬」"}, {"desc": "打你屁股、数落你「怎么几下就哭了」"}, {"desc": "说下手重了，让你过来让他看看伤"}, {"desc": "说要把你圈在府里安稳待着"}, {"desc": "哄你「小兔子都哄了」，说唱好了就给奖励"}], "tone_summary": "（自动）公子视角独白，语气以平静、命令、询问为主，题材偏古风。", "genre_tags": ["古风", "治愈", "敏感"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被公子倾诉/照顾/管教的一方（你）", "signature_elements": ["戒尺", "绑", "打屁股"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "梨园春的后台，几个兵痞正拽着一个年轻戏子往外拖。他穿着军装走进来，靴声在木地板上叩响，眼神冷得像刀。他抬手，拦下了那些人。"}, {"type": "line", "speaker": "公子", "text": "给他妈！干嘛的。放开他。吴副官。把这个绑起来带过去。好好找找不着。管他妈谁家公子，老子们一枪崩了他。就他，左膀右臂都击毙了。走。快点。老子。你好。"}, {"type": "narr", "text": "兵痞们灰溜溜地被押走。他转身，看着那个惊魂未定的人，语气带着压不住的怒意。"}, {"type": "line", "speaker": "公子", "text": "这就是你所谓的不想靠我，一定要做出名堂来给我看看。一出戏还没唱上，就让这种混蛋给缠上。如果今天我不来，你是不是就得跟他走了？跟我回话。"}, {"type": "narr", "text": "她低着头不说话。他上前一步，声音沉下来。"}, {"type": "line", "speaker": "公子", "text": "你要是不回去，这梨园春的人，有一个算一个，老子都崩了。你看我敢不敢。"}, {"type": "narr", "text": "她终于被他带回府上。一路上，她始终沉默。他坐在车里，侧头看她，语气缓和了些。"}, {"type": "line", "speaker": "公子", "text": "一路上都这么沉默，怎么？生气了？梨园春以后还是别去了。你要是喜欢唱戏，在家里唱也是一样。这世道这么乱，戏园子里面鱼龙混杂的。这次正好是我撞见，下次要再有人想占便宜怎么办。怪听话。乖乖听话。"}, {"type": "narr", "text": "她忽然开口，说要继续唱戏。他眉头一皱，语气带着冷。"}, {"type": "line", "speaker": "公子", "text": "之前在上海定做的旗袍到了，你待会去试试。好好看。好好说你不听了是吧？就非他妈今天要顶嘴是吧？你过来。过来。好说。倒说都不听。你哪来这么多脾气。说话。不说什么？"}, {"type": "line", "speaker": "公子", "text": "你今天就试试，到底是你嘴硬，还是我这戒尺硬。站起来。面对我。是你自己动手，还是我来。一。二。三。"}, {"type": "narr", "text": "她咬着牙没有动。他沉着脸，手里的戒尺一下一下落下来。她始终没有躲，却也没有哭。"}, {"type": "line", "speaker": "公子", "text": "刚刚那个王八蛋跑哪了？这里吗？还是这里。这里。又或者是，这里。这才几下，怎么就哭了？刚刚打屁股打这么狠，可你这辈子都没哭，怎么还越哭越厉害了？不是嫌弃你。又怎么会嫌弃你。"}, {"type": "narr", "text": "他放下戒尺，伸手把人拉过来，语气带着后悔的心疼。"}, {"type": "line", "speaker": "公子", "text": "过来。今天下手确实重了点。来。让我看看。不是我非要把你圈在府里面。可是你看现在世道这么乱。到处都在打仗。你除了我以外的话可怎么办。"}, {"type": "line", "speaker": "公子", "text": "你就安安稳稳地待在府上。没事呢？咱就跟别的太太喝喝茶。喝喝咖啡。打打麻将。你说这又啥不好？不想做尽此劝。怕回头不要你。你这整天胡思乱想什么呢？是我对你不够好吗？还是。我夜里不在。才让你白天有功夫。胡思乱想的。"}, {"type": "narr", "text": "她低着头，小声说，怕他嫌她。他叹了口气，语气软下来，带着无奈的宠溺。"}, {"type": "line", "speaker": "公子", "text": "来。我的宝贝。过来。刚刚那几下打得也不狠。怎么小兔子都红了？我听你柔柔。这里是不是也红了。不如。夫人现在就这个样子。将那出。大闹销金帐。再唱一回。就唱得好了。我便给你。"}, {"type": "narr", "text": "她红着脸，轻轻地靠进他怀里。他低头看着她，眼底终于有了笑意。乱世里的金丝雀，也许飞不出那座府邸，但至少，笼子是他亲手搭的，笼里是她最安稳的巢。"}]}, {"no": 32, "id": "DfF2fzX_-V0", "title": "The SP video in the computer was found by your boss", "title_zh": "电脑里的责罚视频被老板发现了 (The SP video in the computer was found by your boss)", "duration": "00:08:55", "link": "https://www.youtube.com/watch?v=DfF2fzX_-V0", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我这边都结束了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "你把剩下的发给我。", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:00:20", "text": "我帮你一起做。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "电脑死机，发不出去。", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:00:36", "text": "我记得我之前教过你怎么设置自动保存。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:00:44", "text": "那问题不大，来我帮你看看。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:00:53", "text": "哎呀，你是说——", "speaker": "上司", "tone": "撒娇", "sound": []}, {"ts": "00:00:56", "text": "磁盘都满了，电脑能不卡吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:00:59", "text": "你把这些东西放到别的盘就好了。", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:01:03", "text": "你看，你看这个。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:06", "text": "这个。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "怎么都是视频文件啊？真的是什么？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "惩罚训诫。", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:01:16", "text": "SP打屁股。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:19", "text": "资料在这儿。然后——", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "先把资料发过去吧。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "好了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "那走吧，下班。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "我开车送你回去。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "想聊几句啊！", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "聊什么？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "DS关系吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:01:54", "text": "经验什么？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "经验？我也懂这些。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:01:58-00:02:20", "text": "那说说你的理解吧。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "嗯。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "惩罚。", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:02:27", "text": "训诫。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "在DS关系里，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "重点并不是训诫和疼痛，", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:02:36", "text": "而是爱和臣服。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "你不应该因为恋痛或者预防，", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:02:42", "text": "而去尝试。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:44", "text": "而是要懂得臣服于一个人。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:46", "text": "令你踏实。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:49", "text": "引领你前行。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:51", "text": "而会鼓励你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "鼓励你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "爱好平凡，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "天高海阔，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "却还能，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "保护你一颗赤子之心的人。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "懂吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:03:07", "text": "所以最近是脑袋里面，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:09", "text": "装了这些事情，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "才没把工作放在心上的。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "对吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:03:16", "text": "那作为你的直属上司，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "发现你工作的效率明显下降，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "脑袋里面整天想着有的没的，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "我是要严厉地批评你的。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "因为我之前对你的了解，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "我觉得这样足够了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "但是现在我了解你更多了一些，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "我觉得除此之外，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "你可能还需要一些，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "肉体上的严厉惩罚，", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:03:48", "text": "才能真正记住教训。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "你觉得呢？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:03:54", "text": "说什么大蠢蛋。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "我主张严厉地惩罚你。", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:04:01", "text": "那你希望我主张要怎么严厉地惩罚你呢？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:04:05", "text": "要像视频那样，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:08", "text": "打你的屁股吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:04:12", "text": "这样你能够记住教训，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:15", "text": "不再犯吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:04:18", "text": "好。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "自己趴到腿上来。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "你最近总是在工作的时候走神。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "之前我还以为是你工作太累了。", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:04:44", "text": "现在看来，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:48", "text": "是脑子里面装了不该有的东西。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:04:53", "text": "今天先罚你三十下。", "speaker": "上司", "tone": "责备", "sound": []}, {"ts": "00:04:57", "text": "服不服？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:02", "text": "服气就好。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "以后还敢不敢？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "说话。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:24", "text": "不要摆出一副委屈的样子。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:29", "text": "我罚你罚错了吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:05:35", "text": "大蠢蛋。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:44", "text": "没有就好好地反省。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:49", "text": "以后还敢不敢不专心工作。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:05:54", "text": "看起来乖乖巧巧、努力用心，", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:05:58", "text": "其实脑子里面，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:03", "text": "都在想一些，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "有的没的。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:12", "text": "是不是？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "所以以后上班的时候，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "专心工作。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:23", "text": "再敢这个样子，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:26", "text": "就不是三十下这么简单了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:29", "text": "记住了没？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:32", "text": "大蠢蛋。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:35", "text": "记住了没？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:39", "text": "对。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:41", "text": "好好地记住。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:43", "text": "起来吧。", "speaker": "上司", "tone": "命令", "sound": []}, {"ts": "00:06:45", "text": "怎么还哭了？", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:06:47", "text": "这么久了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "好了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:52", "text": "罚过了，", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:06:55", "text": "这件事情就过去了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:06:58", "text": "还害羞了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:03", "text": "没想到我也懂这些。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:14", "text": "之前也会很喜欢我。", "speaker": "上司", "tone": "宠溺", "sound": []}, {"ts": "00:07:20", "text": "既然这样的话，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "以后由我，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:27", "text": "来做那个让你踏实的人。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:30", "text": "可以吗？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:07:34", "text": "是你抬起头了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:36", "text": "嘴巴张这么大。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:38", "text": "其实呢，", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:07:41", "text": "我也注意你很久了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:43", "text": "工作很认真，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:45", "text": "待人和气，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:48", "text": "也很善良。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:50", "text": "虽然有时候迷迷糊糊的吧。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:52", "text": "不过，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:55", "text": "你蛮可爱的。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:57", "text": "所以，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:07:59", "text": "昨晚你朋友，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:02", "text": "我来照顾你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:04", "text": "来保护你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "当然了，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:09", "text": "也会引导你和训诫你。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:11", "text": "这样好不好？", "speaker": "上司", "tone": "撒娇", "sound": []}, {"ts": "00:08:14", "text": "傻丫头？", "speaker": "上司", "tone": "询问", "sound": []}, {"ts": "00:08:16", "text": "你可要想好了。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:18", "text": "从今以后，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:21", "text": "你负责向下生长，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "我就负责，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:25", "text": "帮你修剪枝丫。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:28", "text": "以后要是再做错事情，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:30", "text": "公司里的主管，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:33", "text": "会严肃地批评。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:35", "text": "回到家，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:37", "text": "哄一哄，", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:40", "text": "打你的小屁股。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:42", "text": "听到了没？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "疼。", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:08:45", "text": "都没用力。", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "疼。", "speaker": "上司", "tone": "温柔", "sound": []}, {"ts": "00:08:45", "text": "肚子饿了没？", "speaker": "上司", "tone": "平静", "sound": []}, {"ts": "00:08:45", "text": "带你去吃夜宵好不好？", "speaker": "上司", "tone": "撒娇", "sound": []}], "scene": "职场 S 属性调娇。说话者是你「直属上司／老板」，你是他手下员工。情境起点：他来帮你修死机的电脑，意外发现你盘里存着 SP（打屁股）视频，借机把你叫上车，先给你上一堂「DS 关系里重点是爱与臣服」的课，再以「工作效率下降」为由把你趴到腿上打屁股娇训，最后表白早就在意你、以后由他做让你踏实的人，并约法三章「公司严厉批评、回家打小屁股」。整体是「老板撞破小秘密后顺势调娇」，基调暧昧、掌控、甜。", "behaviors": [{"desc": "帮你看电脑、发现硬盘满了死机"}, {"desc": "发现你盘里存着 SP 视频文件"}, {"desc": "车上和你聊 DS 关系，讲重点在爱与臣服"}, {"desc": "让你自己趴到他腿上受罚"}, {"desc": "说先罚三十下，问你服不服"}, {"desc": "罚完让你起来，说「发过了就过去了」"}, {"desc": "表白早注意你很久，以后由他做让你踏实的人"}, {"desc": "问疼不疼、带你去吃宵夜"}], "tone_summary": "（自动）上司视角独白，语气以平静、询问、温柔为主，题材偏职场。", "genre_tags": ["职场", "治愈"], "genre_main": "职场", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被上司倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "办公室的灯还亮着。她对着电脑发呆，屏幕上的文档半天没动。身后传来脚步声，他俯身看了一眼，语气带着上级惯常的温和。"}, {"type": "line", "speaker": "上司", "text": "我这边都结束了。你把剩下的发给我，我帮你一起做。电脑死机，发不出去？我记得我之前教过你怎么设置自动保存。那问题不大，来，我帮你看看。哎呀，你是说——磁盘都满了，电脑能不卡吗？你把这些东西放到别的盘就好了。"}, {"type": "narr", "text": "他点开磁盘管理，鼠标划过那一长串文件名，动作忽然顿住了。她坐在旁边，脸色一下子白了。他转头看她，语气带着了然。"}, {"type": "line", "speaker": "上司", "text": "你看，你看这个。这个。怎么都是视频文件啊？真的是什么？惩罚训诫。SP打屁股。资料在这儿。然后——先把资料发过去吧。好了。那走吧，下班。我开车送你回去。"}, {"type": "narr", "text": "车里很安静。她坐在副驾，低着头不敢看他。他开着车，忽然开口，语气平静得像在聊一件很普通的事。"}, {"type": "line", "speaker": "上司", "text": "想聊几句啊！聊什么？DS关系吗？经验什么？经验？我也懂这些。那说说你的理解吧。嗯。惩罚。训诫。在DS关系里，重点并不是训诫和疼痛，而是爱和臣服。你不应该因为恋痛或者猎奇，而去尝试，而是要懂得臣服于一个人，令你踏实，引领你前行。"}, {"type": "narr", "text": "她听着他的话，心跳一点点加快。他顿了顿，声音低下来，带着认真的分量。"}, {"type": "line", "speaker": "上司", "text": "而会鼓励你，鼓励你——爱好平凡，天高海阔，却还能保护你一颗赤子之心的人。懂吗？所以最近是脑袋里面装了这些事情，才没把工作放在心上的，对吗？那作为你的直属上司，发现你工作的效率明显下降，脑袋里面整天想着有的没的，我是要严厉地批评你的。"}, {"type": "narr", "text": "她低下头，脸红得厉害。他侧头看她一眼，语气带着一点意味深长的转折。"}, {"type": "line", "speaker": "上司", "text": "因为我之前对你的了解，我觉得这样足够了。但是现在我了解你更多了一些，我觉得除此之外，你可能还需要一些肉体上的严厉惩罚，才能真正记住教训。你觉得呢？说什么大蠢蛋。我主张严厉地惩罚你。那你希望我主张要怎么严厉地惩罚你呢？要像视频那样，打你的屁股吗？这样你能够记住教训，不再犯吗？"}, {"type": "narr", "text": "她声音细若蚊蚋，好半天才挤出两个字。他听完，方向盘一转，把车停在路边，语气带着不容拒绝的从容。"}, {"type": "line", "speaker": "上司", "text": "好。自己趴到腿上来。你最近总是在工作的时候走神，之前我还以为是你工作太累了。现在看来，是脑子里面装了不该有的东西。今天先罚你三十下。服不服？服气就好。以后还敢不敢？说话。不要摆出一副委屈的样子，我罚你罚错了吗？大蠢蛋。"}, {"type": "narr", "text": "她趴在车座上，咬着唇，一下一下地挨着。他一边打，一边带着恨铁不成钢的数落。"}, {"type": "line", "speaker": "上司", "text": "没有就好好地反省。以后还敢不敢不专心工作？看起来乖乖巧巧、努力用心，其实脑子里面，都在想一些有的没的，是不是？所以以后上班的时候，专心工作。再敢这个样子，就不是三十下这么简单了。记住了没？大蠢蛋。记住了没？对，好好地记住。"}, {"type": "narr", "text": "三十下打完，他停下手，语气软下来。她趴在座位上，肩膀轻轻抖着。"}, {"type": "line", "speaker": "上司", "text": "起来吧。怎么还哭了？这么久了。好了。罚过了，这件事情就过去了。还害羞了？没想到我也懂这些。之前也会很喜欢我？既然这样的话，以后由我，来做那个让你踏实的人。可以吗？"}, {"type": "narr", "text": "她抬起头，眼睛红红的，愣愣地看着他。他看着她这副模样，忍不住笑了，语气带着认真的温柔。"}, {"type": "line", "speaker": "上司", "text": "是你抬起头了，嘴巴张这么大。其实呢，我也注意你很久了。工作很认真，待人和气，也很善良。虽然有时候迷迷糊糊的吧。不过，你蛮可爱的。所以，昨晚你朋友——我来照顾你，来保护你。当然了，也会引导你和训诫你。这样好不好？傻丫头？"}, {"type": "narr", "text": "她红着脸，轻轻点了一下头。他看着她，眼底带着纵容的笑意，说出那句郑重的承诺。"}, {"type": "line", "speaker": "上司", "text": "你可要想好了。从今以后，你负责向下生长，我就负责，帮你修剪枝丫。以后要是再做错事情，公司里的主管，会严肃地批评。回到家，哄一哄，打你的小屁股。听到了没？疼？都没用力。疼。肚子饿了没？带你去吃夜宵，好不好？"}, {"type": "narr", "text": "她破涕为笑，眼睛亮亮的。他发动车子，朝她笑了笑。夜风从窗外灌进来，她靠进椅背，忽然觉得——原来被人接管、被人在意，是这样一种踏实的感觉。而明天上班，她大概会格外专心。"}]}, {"no": 33, "id": "fnEWYu9wk6k", "title": "The cat who loves you (tear warning)", "title_zh": "爱着你的那只猫（催泪预警） (The cat who loves you (tear warning))", "duration": "00:05:19", "link": "https://www.youtube.com/watch?v=fnEWYu9wk6k", "enriched": true, "lines": [{"ts": "00:00:00", "text": "这是一个小故事。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:02", "text": "猫有九条命。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:05", "text": "每一次死去，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:08", "text": "都是一次转身，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:11", "text": "为了换一个躯壳，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:14", "text": "来到你面前。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:17", "text": "九个十年，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "刚好够做完一生。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:22", "text": "现在是凌晨四点。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:25", "text": "再过一会儿，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "天就要亮了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "我找好了喜欢的地方。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:00:34", "text": "抱歉，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "最后的路程，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:40", "text": "不能让你陪着我了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "还记得我们第一次见面吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:00:46", "text": "你拿着罐头在树丛边，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "我一眼就瞧出了你的心思，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:54", "text": "想用一个罐头就把我骗走。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:58", "text": "天真的姑娘。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "后来啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "看你天天都来喂猫，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "没有一只猫咪上前，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "每次都等你离开之后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "他们才会出现，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:21", "text": "把罐头哄抢光。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "那我看你失落的样子就想，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "去哄哄你这个小姑娘吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "所以跟你回家，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "才不是为了固定粮仓。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "回到家之后你对我", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "说，从今以后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:50", "text": "我就是你的猫咪了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "其实我已经在野外，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "流浪两年了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "说来，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "你才是需要被人照顾的小孩子呢。", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:02:06", "text": "你学习很辛苦，", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:02:10", "text": "所以你在看书的时候，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:14", "text": "我选择趴在你的背上。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "其实我都有在背后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "默默看着你，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "陪着你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "后来，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "你把更多时间交给了工作，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "我很少看见你开心的样子，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "也很少再来闹我。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "你带我搬去了自己的房子，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:41", "text": "给我换了更大的软垫，", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:02:43", "text": "但我还是喜欢趴在你的背上，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:02:46", "text": "压着你，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:49", "text": "直到你抱怨，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:52", "text": "腿都麻了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:54", "text": "喜欢看你笑着喊我的名字，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:02:57", "text": "揉揉我的脑袋，", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:03:00", "text": "用你的下巴，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "给我梳毛。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:03:06", "text": "喜欢在冬日，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:03:08", "text": "阳光正好的午后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "你眯着眼，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:14", "text": "和你一起晒太阳。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "我多想，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "能趴你再久一点，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "再久一点呢。", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:03:25", "text": "我先看不见，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:29", "text": "渐渐看不见。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:34", "text": "我先看不见，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:37-00:03:41", "text": "渐渐看不见。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "视力没有了依靠，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "也不能准确地判断跳跃的距离。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "在第七次跳沙发的时候，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "我摔下来了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:00", "text": "我就知道了，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:03", "text": "我要走了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "你实际上对我说很羡慕我，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "能当一只猫咪，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "不会悲喜，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "也不会欣喜若狂。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "我这个淘气鬼。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:25", "text": "但是我是真的很爱你，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:04:30", "text": "所以这次就让我任性一回。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "下次见面，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:35", "text": "换我去找你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:38", "text": "等着那一天，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:40", "text": "我会，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "蹲在家门口。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "你回来的时候，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:48", "text": "我就滚到你脚边。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:51", "text": "你一定可以认出我，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:54", "text": "然后，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "带我回家。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "对吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:05:02", "text": "姐姐。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:05", "text": "一定是。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:08", "text": "所以，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:11", "text": "再见了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "永远爱你的，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:05:15", "text": "猫咪。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "猫咪第一人称临终告白（催泪向）。说话者是一只陪伴你多年的猫（自称「猫咪」），你是它的人类「姐姐」。情境起点：它已是第九次转世、快走到生命尽头，在凌晨四点向你道别。它回忆初见你拿罐头灯、跟你回家后你把它当「弟弟」照顾，它默默陪你读书、趴你腿上晒太阳；第七次跳沙发摔下来它便知道自己要走了，最后许诺下被子还来做你的猫、蹲在家门口等你带它回家。整体是「宠物跨世陪伴」型温柔告白，基调治愈、感伤、极深情。", "behaviors": [{"desc": "回忆你拿罐头灯在树丛边、它一眼瞧出你的心思"}, {"desc": "跟你回家后，你说「从今以后我就是你弟弟了」"}, {"desc": "你学习辛苦，它选择趴在你背上陪你"}, {"desc": "喜欢冬日午后和你一起晒太阳、趴你久一点"}, {"desc": "第七次跳沙发摔下来，它知道「我要走了」"}, {"desc": "许诺下被子还来找你、蹲在家门口等你带它回家"}], "tone_summary": "（自动）他视角独白，语气以平静、宠溺、询问为主，题材偏古风。", "genre_tags": ["古风", "治愈"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "凌晨四点，天还没有亮。我趴在窗台上，望着客厅里熟睡的你，在心里把想说的话，又默默念了一遍。"}, {"type": "line", "speaker": "他", "text": "这是一个小故事。猫有九条命。每一次死去，都是一次转身，为了换一个躯壳，来到你面前。"}, {"type": "narr", "text": "月光落在我身上。我低头舔了舔自己有些褪色的毛，忽然觉得，时间好像真的快到了。"}, {"type": "line", "speaker": "他", "text": "九个十年，刚好够做完一生。现在是凌晨四点。再过一会儿，天就要亮了。我找好了喜欢的地方。"}, {"type": "narr", "text": "我回过头，最后看了你一眼。你睡得很沉，呼吸均匀，被子一角还搭在你肩上。我轻声开口，像怕吵醒你。"}, {"type": "line", "speaker": "他", "text": "抱歉，最后的路程，不能让你陪着我了。还记得我们第一次见面吗？"}, {"type": "narr", "text": "那天的画面在我眼前浮现。树丛边，你蹲在那里，手里举着一罐罐头，眼睛亮亮地看着我。"}, {"type": "line", "speaker": "他", "text": "你拿着罐头在树丛边，我一眼就瞧出了你的心思。想用一个罐头就把我骗走。天真的姑娘。"}, {"type": "narr", "text": "我那时其实在心里笑你——我流浪了那么久，哪是那么容易上当的。可你偏偏，是那么认真的样子。"}, {"type": "line", "speaker": "他", "text": "后来啊！看你天天都来喂猫，没有一只猫咪上前。每次都等你离开之后，他们才会出现，把罐头哄抢光。"}, {"type": "narr", "text": "你蹲在空荡荡的树丛边，失落的样子，我到现在都记得。那一刻我就想，去哄哄你这个小姑娘吧。"}, {"type": "line", "speaker": "他", "text": "所以跟你回家，才不是为了固定粮仓。回到家之后，你对我说，从今以后，我就是你的猫咪了。"}, {"type": "narr", "text": "我那时想，真是个傻姑娘。明明是我自己选了你，你却郑重其事地宣告，好像给了我天大的名分。"}, {"type": "line", "speaker": "他", "text": "其实我已经在野外，流浪两年了。说来，你才是需要被人照顾的小孩子呢。"}, {"type": "narr", "text": "你学习很辛苦，总在书桌前坐到深夜。我不吵你，只是轻轻跳上你的背，趴在那里，假装睡觉。"}, {"type": "line", "speaker": "他", "text": "你学习很辛苦，所以你在看书的时候，我选择趴在你的背上。其实我都有在背后，默默看着你，陪着你。"}, {"type": "narr", "text": "你的体温透过毛衣传过来，带着一点洗衣液的味道。我在你背上，能听见你翻书的声音，一下，又一下。"}, {"type": "line", "speaker": "他", "text": "后来，你把更多时间交给了工作。我很少看见你开心的样子，也很少再来闹我。"}, {"type": "narr", "text": "你带我搬去了自己的房子，给我换了更大的软垫。可我总是跳上你的背，压着你，直到你笑着抱怨腿麻。"}, {"type": "line", "speaker": "他", "text": "你带我搬去了自己的房子，给我换了更大的软垫。但我还是喜欢趴在你的背上，压着你，直到你抱怨，腿都麻了。"}, {"type": "line", "speaker": "他", "text": "喜欢看你笑着喊我的名字，揉揉我的脑袋，用你的下巴，给我梳毛。"}, {"type": "narr", "text": "你的下巴轻轻蹭过我的头顶，一下一下，带着暖意。我眯起眼睛，喉咙里发出咕噜咕噜的声音。"}, {"type": "line", "speaker": "他", "text": "喜欢在冬日，阳光正好的午后，你眯着眼，和你一起晒太阳。"}, {"type": "narr", "text": "阳光透过玻璃落在我们身上，你半睡半醒，手搭在我背上。那时我就想，这样的日子，如果能再久一点就好了。"}, {"type": "line", "speaker": "他", "text": "我多想，能趴你再久一点，再久一点呢。"}, {"type": "narr", "text": "可是最近，我总觉得眼前蒙着一层雾。跳上沙发的时候，脚一软，差点摔下去。"}, {"type": "line", "speaker": "他", "text": "我先看不见。渐渐看不见。视力没有了依靠，也不能准确地判断跳跃的距离。"}, {"type": "narr", "text": "那天傍晚，我像往常一样想跳上沙发。起跳的瞬间，我算错了距离，整个身体撞在沙发边上，摔了下来。"}, {"type": "line", "speaker": "他", "text": "在第七次跳沙发的时候，我摔下来了。我就知道了，我要走了。"}, {"type": "narr", "text": "我趴在地上，缓了很久。你跑过来，把我抱起来，一遍遍问我怎么了。我蹭了蹭你的手心，心里说，别难过。"}, {"type": "line", "speaker": "他", "text": "你实际上对我说很羡慕我，能当一只猫咪。不会悲喜，也不会欣喜若狂。我这个淘气鬼。"}, {"type": "narr", "text": "可你不知道，我这一生所有的情绪，都给了你。开心是因为你，难过也是因为你。"}, {"type": "line", "speaker": "他", "text": "但是我是真的很爱你。所以这次就让我任性一回。下次见面，换我去找你。"}, {"type": "narr", "text": "我最后看了一眼你的睡颜。窗外的天边，泛起一线灰白。我站起身，轻轻地，从窗台跳了下去。"}, {"type": "line", "speaker": "他", "text": "等着那一天，我会蹲在家门口。你回来的时候，我就滚到你脚边。你一定可以认出我，然后，带我回家。对吗？"}, {"type": "narr", "text": "晨光落在我身上，我最后回头望了一眼那扇窗。窗里，你还在睡。而我这一世的心愿，已经了了。"}, {"type": "line", "speaker": "他", "text": "姐姐。一定是。所以，再见了。永远爱你的，猫咪。"}, {"type": "narr", "text": "后来的许多年，你总是会在家门口遇到一只猫。它不靠近，只是远远地看你，眼睛里有说不清的温柔。你知道，那是谁。"}]}]);